DROP TABLE IF EXISTS `daily_sku_features`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `daily_sku_features` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `product_sku` varchar(255) NOT NULL,
  `date` date NOT NULL,
  `is_promotion` tinyint(1) DEFAULT NULL,
  `is_public_holiday` tinyint(1) NOT NULL DEFAULT 0,
  `is_school_term` tinyint(1) NOT NULL DEFAULT 0,
  `sales_data_covered` tinyint(1) NOT NULL DEFAULT 0,
  `temperature_c` decimal(5,2) DEFAULT NULL,
  `temperature_source` varchar(20) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `daily_sku_features_product_sku_date_unique` (`product_sku`,`date`)
) ENGINE=InnoDB AUTO_INCREMENT=7461 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

