--
-- Table structure for table `leakage_reports`
--

DROP TABLE IF EXISTS `leakage_reports`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `leakage_reports` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `batch_id` bigint(20) unsigned DEFAULT NULL,
  `product_id` bigint(20) unsigned DEFAULT NULL,
  `production_line_id` bigint(20) unsigned DEFAULT NULL,
  `warehouse_location` varchar(255) DEFAULT NULL,
  `stock_count_id` bigint(20) unsigned DEFAULT NULL,
  `expected_volume` decimal(12,2) NOT NULL,
  `actual_volume` decimal(12,2) NOT NULL,
  `discrepancy` decimal(12,2) NOT NULL,
  `report_date` date NOT NULL,
  `source` enum('manual','process','stock') NOT NULL DEFAULT 'manual',
  `finding` enum('manual','process_loss','logging_gap','stock_shrinkage') NOT NULL DEFAULT 'manual',
  `detected_by` enum('manual','rule','anomaly') NOT NULL DEFAULT 'manual',
  `severity` enum('review','investigate') DEFAULT NULL,
  `loss_percent` decimal(8,3) DEFAULT NULL,
  `z_score` decimal(8,3) DEFAULT NULL,
  `explanation` text DEFAULT NULL,
  `detection_key` varchar(255) DEFAULT NULL,
  `status` enum('open','acknowledged','resolved') NOT NULL DEFAULT 'open',
  `acknowledged_by` bigint(20) unsigned DEFAULT NULL,
  `acknowledged_at` timestamp NULL DEFAULT NULL,
  `resolution_note` text DEFAULT NULL,
  `resolved_by` bigint(20) unsigned DEFAULT NULL,
  `resolved_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `leakage_reports_detection_key_unique` (`detection_key`),
  KEY `leakage_reports_batch_id_foreign` (`batch_id`),
  KEY `leakage_reports_product_id_foreign` (`product_id`),
