--
-- Table structure for table `production_batches`
--

DROP TABLE IF EXISTS `production_batches`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `production_batches` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned NOT NULL,
  `production_schedule_id` bigint(20) unsigned DEFAULT NULL,
  `batch_date` date NOT NULL,
  `raw_water_volume` decimal(12,2) NOT NULL,
  `bottled_volume` decimal(12,2) NOT NULL,
  `logged_volume` decimal(12,3) DEFAULT NULL,
  `process_loss_percent` decimal(8,3) DEFAULT NULL,
  `status` enum('pending','in_progress','completed','rejected') NOT NULL DEFAULT 'pending',
  `completed_at` timestamp NULL DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `production_batches_production_schedule_id_unique` (`production_schedule_id`),
  KEY `production_batches_user_id_foreign` (`user_id`),
  CONSTRAINT `production_batches_production_schedule_id_foreign` FOREIGN KEY (`production_schedule_id`) REFERENCES `production_schedules` (`id`) ON DELETE SET NULL,
  CONSTRAINT `production_batches_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1831 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

