--
-- Table structure for table `production_schedules`
--

DROP TABLE IF EXISTS `production_schedules`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `production_schedules` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `product_sku` varchar(255) NOT NULL,
  `production_line_id` bigint(20) unsigned NOT NULL,
  `scheduled_date` date NOT NULL,
  `scheduled_time` time NOT NULL,
  `target_units` int(10) unsigned NOT NULL,
  `status` enum('queued','active','complete') NOT NULL DEFAULT 'queued',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `production_schedules_production_line_id_foreign` (`production_line_id`),
  CONSTRAINT `production_schedules_production_line_id_foreign` FOREIGN KEY (`production_line_id`) REFERENCES `production_lines` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1836 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

