--
-- Table structure for table `work_orders`
--

DROP TABLE IF EXISTS `work_orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `work_orders` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `reference` varchar(20) NOT NULL,
  `equipment_id` bigint(20) unsigned NOT NULL,
  `maintenance_plan_id` bigint(20) unsigned DEFAULT NULL,
  `due_on` date DEFAULT NULL,
  `request_id` bigint(20) unsigned DEFAULT NULL,
  `type` enum('preventive','corrective','inspection') NOT NULL,
  `source` enum('plan','request','breakdown') NOT NULL,
  `priority` enum('low','normal','urgent') NOT NULL DEFAULT 'normal',
  `status` enum('open','in_progress','done','cancelled') NOT NULL DEFAULT 'open',
  `reported_by` bigint(20) unsigned DEFAULT NULL,
  `assigned_to` bigint(20) unsigned DEFAULT NULL,
  `description` text NOT NULL,
  `started_at` timestamp NULL DEFAULT NULL,
  `completed_at` timestamp NULL DEFAULT NULL,
  `downtime_minutes` int(10) unsigned DEFAULT NULL,
  `parts_used` text DEFAULT NULL,
  `cost_kes` decimal(12,2) DEFAULT NULL,
  `checklist_results` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`checklist_results`)),
  `completion_notes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `work_orders_reference_unique` (`reference`),
  UNIQUE KEY `work_orders_request_id_unique` (`request_id`),
  KEY `work_orders_reported_by_foreign` (`reported_by`),
  KEY `work_orders_assigned_to_foreign` (`assigned_to`),
  KEY `work_orders_status_priority_index` (`status`,`priority`),
  KEY `work_orders_equipment_id_completed_at_index` (`equipment_id`,`completed_at`),
  KEY `work_orders_plan_status_index` (`maintenance_plan_id`,`status`),
  CONSTRAINT `work_orders_assigned_to_foreign` FOREIGN KEY (`assigned_to`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `work_orders_equipment_id_foreign` FOREIGN KEY (`equipment_id`) REFERENCES `equipment` (`id`),
  CONSTRAINT `work_orders_maintenance_plan_id_foreign` FOREIGN KEY (`maintenance_plan_id`) REFERENCES `maintenance_plans` (`id`) ON DELETE SET NULL,
  CONSTRAINT `work_orders_reported_by_foreign` FOREIGN KEY (`reported_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `work_orders_request_id_foreign` FOREIGN KEY (`request_id`) REFERENCES `requests` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=308 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

